write('learn.html','''<main class="container section" data-hub="learn"><span class="eyebrow">Learn</span><div class="hub-head"><h1>Learn by subject</h1><p>Pick a subject, then practise topic by topic. Every question gives instant feedback and a short explanation.</p></div><div id="hubView"></div></main>''',scripts='<script src="bank.js"></script><script src="bank-extra.js"></script>',title='Learn')
write('past-questions.html','''<main class="container section" data-hub="past"><span class="eyebrow">Past questions</span><div class="hub-head"><h1>Past Questions</h1><p>Choose an examination, a subject and a set, then answer one question at a time and see straight away if you were right.</p></div><div id="hubView"></div></main>''',scripts='<script src="bank.js"></script><script src="bank-extra.js"></script>',title='Past Questions')
write('smart-quiz.html','''<main class="container section" data-hub="smart"><span class="eyebrow">Smart quiz</span><div class="hub-head"><h1>Build your own quiz</h1><p>Subject, then topic, then difficulty, then how many questions. We will mark each answer and move to the next one for you.</p></div><div id="hubView"></div></main>''',scripts='<script src="bank.js"></script><script src="bank-extra.js"></script>',title='Smart Quiz')
write('dashboard.html','''<main class="container section" data-hub="dashboard"><span class="eyebrow">My dashboard</span><div id="hubView" style="margin-top:8px"></div></main>''',scripts='<script src="bank.js"></script><script src="bank-extra.js"></script>',title='My Dashboard')
write('leaderboard.html','''<main class="container section" data-hub="leaderboard"><span class="eyebrow">Leaderboard</span><div class="hub-head"><h1>Leaderboard 🏆</h1><p>See how your XP compares. Your name stays hidden unless you choose to show it.</p></div><div id="hubView"></div></main>''',scripts='',title='Leaderboard')
write('search.html','''<main class="container section" data-hub="search"><span class="eyebrow">Search</span><div class="hub-head"><h1>Search</h1><p>Find subjects, topics, practice questions, scholarships and schools.</p></div><form class="searchbar" action="search.html" method="get" role="search"><input id="q" type="search" name="q" placeholder="🔎 Search subjects, topics, schools, past questions…" aria-label="Search" autocomplete="off"><button class="btn primary" type="submit">Search</button></form><div id="hubView"></div></main>''',scripts='<script src="bank.js"></script><script src="bank-extra.js"></script><script src="directory.js"></script>',title='Search')
write('scholarships.html','''<main class="container section" data-hub="scholarships"><span class="eyebrow">Scholarships</span><div class="hub-head"><h1>Scholarships and opportunities</h1><p>Only verified opportunities are listed: each one was checked against its official website on 25 November 2026. Deadlines change every year, so always read the official notice before you apply.</p></div><div class="searchbar"><input id="dirFilter" type="search" placeholder="🔎 Filter scholarships…" aria-label="Filter scholarships" autocomplete="off"></div><div id="hubView"></div><div class="card" style="margin-top:22px"><h3 style="margin:0 0 6px">How to spot a fake scholarship</h3><ul class="checklist"><li><b>Use the official website only.</b> Type the address yourself. Copycat sites exist, and even the Commonwealth Scholarship Commission has warned about a look-alike organisation.</li><li><b>Never pay to apply</b>, and never pay an agent for a “guaranteed” place. Official scholarship bodies do not sell places.</li><li><b>Take deadlines and requirements from the official notice</b>, not from social media posts or forwarded WhatsApp messages.</li><li><b>Do not send</b> passports, certificates or ID documents to unofficial contacts.</li><li>If an offer sounds too good to be true, ask a teacher or school counsellor before you reply.</li></ul></div></main>''',scripts='<script src="directory.js"></script>',title='Scholarships')
write('schools.html','''<main class="container section" data-hub="schools"><span class="eyebrow">Schools</span><div class="hub-head"><h1>Schools directory</h1><p>Public universities with their official websites. Entry requirements, cut-offs and deadlines change every year, so always read the official admissions page.</p></div><div class="searchbar"><input id="dirFilter" type="search" placeholder="🔎 Search by name, town or region…" aria-label="Filter schools" autocomplete="off"></div><div id="hubView"></div><div class="notice warn" style="margin-top:22px"><b>Stay safe when applying.</b> Universities, including KNUST, have warned applicants about people who offer to “secure” admission or hall places for a fee. Use only the official website. You can also check that an institution is accredited with the Ghana Tertiary Education Commission at <a href="https://gtec.edu.gh" target="_blank" rel="noopener noreferrer">gtec.edu.gh</a>.</div></main>''',scripts='<script src="directory.js"></script>',title='Schools')
write('ai-tutor.html','''<main class="container section"><span class="eyebrow">AI Tutor</span><div class="hub-head"><h1>Your personal AI tutor <span class="pill soon">Coming soon</span></h1><p>We are building a tutor that can explain topics, work through problems step by step and mark your answers. It will have five modes.</p></div><div class="cards"><div class="card"><div class="stat"><div class="num" style="font-size:1.8rem">🧑‍🏫</div><div><b>Explain mode</b><div class="muted">Explains a topic in simple words, at your level.</div></div></div></div><div class="card"><div class="stat"><div class="num" style="font-size:1.8rem">🧮</div><div><b>Solve mode</b><div class="muted">Works through calculations one step at a time.</div></div></div></div><div class="card"><div class="stat"><div class="num" style="font-size:1.8rem">📝</div><div><b>Exam mode</b><div class="muted">Gives an answer in the style that earns marks in exams.</div></div></div></div><div class="card"><div class="stat"><div class="num" style="font-size:1.8rem">🧠</div><div><b>Quiz mode</b><div class="muted">Makes questions on a topic and marks your answers.</div></div></div></div><div class="card"><div class="stat"><div class="num" style="font-size:1.8rem">🔄</div><div><b>Revision mode</b><div class="muted">Builds practice from the topics you find hardest.</div></div></div></div></div><div class="notice" style="margin-top:22px"><b>Until then</b>, you can already practise with the <a href="smart-quiz.html">Smart Quiz</a>, work through the <a href="learn.html">subjects</a>, or <a href="upload.html">upload your own notes</a> and turn them into a quiz.</div></main>''',scripts='',title='AI Tutor')
write('pricing.html','''<main class="container section"><span class="eyebrow">Pricing</span><div class="hub-head"><h1>Free to use today</h1><p>Everything on this site is free right now. We may add a Premium option later for students who want more. You will be told clearly, with prices, before anything is ever charged.</p></div><div class="cards"><div class="card"><h3 style="margin-top:0">Free <span class="pill ok">Available now</span></h3><ul class="checklist"><li>Practice questions and smart quizzes</li><li>Quizzes made from your own notes</li><li>Dashboard, streak and XP</li><li>Scholarship and school directories</li></ul></div><div class="card"><h3 style="margin-top:0">Premium <span class="pill soon">Planned</span></h3><ul class="checklist"><li>Unlimited AI tutoring</li><li>A larger question bank</li><li>Mock examinations</li><li>Personal study plans and analytics</li><li>No advertisements</li></ul></div></div></main>''',scripts='',title='Pricing')
write('more.html','''<main class="container section"><span class="eyebrow">Explore</span><div class="hub-head"><h1>Everything in one place</h1><p>All the sections of Concord’s as your Tutor.</p></div><div class="explore"><a class="tile" href="learn.html"><span class="ico">📚</span><b>Learn</b><span class="meta">Subjects and topics</span></a><a class="tile" href="past-questions.html"><span class="ico">🗂️</span><b>Past Questions</b><span class="meta">By examination and subject</span></a><a class="tile" href="smart-quiz.html"><span class="ico">🧠</span><b>Smart Quiz</b><span class="meta">Choose subject, topic and level</span></a><a class="tile" href="upload.html"><span class="ico">📝</span><b>My Notes</b><span class="meta">Turn your own notes into a quiz</span></a><a class="tile" href="dashboard.html"><span class="ico">📊</span><b>Dashboard</b><span class="meta">Progress, streak and weak topics</span></a><a class="tile" href="leaderboard.html"><span class="ico">🏆</span><b>Leaderboard</b><span class="meta">Compare your XP</span></a><a class="tile" href="scholarships.html"><span class="ico">🎓</span><b>Scholarships</b><span class="meta">Verified opportunities</span></a><a class="tile" href="schools.html"><span class="ico">🏫</span><b>Schools</b><span class="meta">University directory</span></a><a class="tile" href="ai-tutor.html"><span class="ico">🤖</span><b>AI Tutor</b><span class="meta">Coming soon</span></a><a class="tile disabled" href="#"><span class="ico">⏱️</span><b>Mock Exams</b><span class="meta">Timed practice papers · coming soon</span></a><a class="tile disabled" href="#"><span class="ico">🧑‍🏫</span><b>Tutors</b><span class="meta">Find a tutor near you · coming soon</span></a><a class="tile" href="pricing.html"><span class="ico">💳</span><b>Pricing</b><span class="meta">Free today</span></a><a class="tile" href="progress.html"><span class="ico">📈</span><b>My Progress</b><span class="meta">Quiz history</span></a><a class="tile" href="about.html"><span class="ico">ℹ️</span><b>About</b><span class="meta">How the app works</span></a></div></main>''',scripts='',title='Explore')
